// NPi `/web` page: one CLI session in a browser on the LAN, rendered with NPi Desktop's own chat
// components (desktop-ui.js, generated by desktop/scripts/build-web-ui.mjs). This file is the page's
// whole state: the session's raw messages from the `/web` WebSocket, turned into the entries
// Desktop's ChatView renders. No tabs, profiles or settings: the server serves this one session.
(() => {
	"use strict";

	const h = React.createElement;
	const { ChatView, QueueStrip, Icon } = window;

	// ---------- raw messages → Desktop transcript entries ----------

	const entryCache = new WeakMap();

	function timeOf(msg) {
		const d = new Date(msg?.timestamp ?? Date.now());
		return Number.isNaN(d.getTime())
			? window.timeNow()
			: [d.getHours(), d.getMinutes(), d.getSeconds()].map(n => String(n).padStart(2, "0")).join(":");
	}

	function userEntry(msg, index) {
		const blocks = Array.isArray(msg.content) ? msg.content : [{ type: "text", text: String(msg.content ?? "") }];
		const { text, images } = window.adaptUserContent(blocks);
		if (!text && images.length === 0) return null;
		return { _id: `u:${msg.timestamp ?? index}`, kind: "user", time: timeOf(msg), ts: msg.timestamp ?? null, text, images };
	}

	function assistantEntry(msg, index, failure, live) {
		let thought = null;
		const blocks = [];
		for (const block of Array.isArray(msg.content) ? msg.content : []) {
			if (!block || typeof block !== "object") continue;
			if (block.type === "thinking" && block.thinking?.trim()) thought = block.thinking;
			else if (block.type === "text" && block.text?.trim()) blocks.push({ type: "text", text: block.text });
		}
		if (!live && blocks.length === 0 && !thought && !failure) return null;
		const u = msg.usage;
		const tokensIn = u?.input ?? null;
		const tokensOut = u?.output ?? null;
		return {
			_id: `a:${msg.timestamp ?? index}`,
			kind: "assistant",
			time: timeOf(msg),
			ts: msg.timestamp ?? null,
			model: msg.model ?? null,
			thought,
			lead: thought ? "thinking" : null,
			blocks,
			streaming: !!live,
			thinkingActive: live ? blocks.length === 0 && !!thought : undefined,
			completed: !live,
			tokens: tokensIn != null || tokensOut != null ? (tokensIn ?? 0) + (tokensOut ?? 0) : null,
			tokensIn,
			tokensOut,
			...(failure ? { failure } : {}),
		};
	}

	/** One tool card per call: Desktop's start card, then its streamed or final result. */
	function toolEntry(call, time, result, partial, timing) {
		let card = window.buildToolStartCard(
			{ toolName: call.name, toolCallId: call.id, args: call.arguments, intent: call.intent },
			time,
		);
		card = { ...card, _id: `t:${call.id}`, _startMs: timing?.start };
		if (result) {
			const done = window.finalizeToolCard(card, { result, isError: !!result.isError });
			// A call replayed from history has no timing: show none rather than 0 ms.
			return { ...done, duration: timing?.start && timing.end ? timing.end - timing.start : null };
		}
		if (partial) return window.updateToolCard(card, { partialResult: partial });
		return card;
	}

	function buildEntries(raw, liveIndex, tools, asks) {
		const failures = window.OMP_TURN_STATUS.finalFailures(raw);
		const results = new Map();
		for (const msg of raw) if (msg?.role === "toolResult") results.set(msg.toolCallId, msg);
		let out = [];
		const askAt = new Map();
		for (const ask of asks) {
			const list = askAt.get(ask.after) ?? [];
			list.push(ask);
			askAt.set(ask.after, list);
		}
		raw.forEach((msg, index) => {
			if (msg && typeof msg === "object") {
				if (msg.role === "user") {
					let entry = entryCache.get(msg);
					if (entry === undefined) entryCache.set(msg, (entry = userEntry(msg, index)));
					if (entry) out.push(entry);
				} else if (msg.role === "assistant") {
					const live = index === liveIndex;
					const failure = failures.get(index) ?? null;
					const cached = !live && entryCache.get(msg);
					let entry = cached && cached.failure === (failure ?? undefined) ? cached : undefined;
					if (entry === undefined) {
						entry = assistantEntry(msg, index, failure, live);
						if (!live) entryCache.set(msg, entry);
					}
					if (entry) out.push(entry);
					for (const block of Array.isArray(msg.content) ? msg.content : []) {
						if (block?.type !== "toolCall" || typeof block.id !== "string") continue;
						const done = results.get(block.id);
						const result = done
							? { content: done.content, details: done.details, isError: done.isError }
							: tools.ended.get(block.id);
						const partial = tools.partial.get(block.id);
						const key = `${block.id}|${result ? "r" : partial ? "p" : "s"}`;
						const prev = tools.cards.get(block.id);
						let card = prev && prev.key === key && prev.call === block && prev.result === result && prev.partial === partial
							? prev.card
							: null;
						if (!card) {
							card = toolEntry(block, timeOf(msg), result, partial, tools.timing.get(block.id));
							tools.cards.set(block.id, { key, call: block, result, partial, card });
						}
						out.push(card);
						if (result && block.name === "todo" && !result.isError && result.details?.phases?.length) {
							const host = out.findLastIndex(m => m.kind === "assistant");
							if (host !== -1) out = window.withInlinePlan(out, host, window.buildInlinePlan(result.details.phases));
						}
					}
				}
			}
			for (const ask of askAt.get(index) ?? []) out.push(ask);
		});
		for (const [after, list] of askAt) if (after >= raw.length) out.push(...list);
		return window.markLatestPlanLive(out);
	}

	// ---------- asks (approvals, select, confirm, input, editor, ask dialog) ----------

	function askFromRequest(request, after) {
		const base = {
			_id: `ask:${request.id}`,
			kind: "ask",
			method: request.method,
			id: request.id,
			time: window.timeNow(),
			title: request.title ?? "",
			options: [],
			answered: false,
			cancelled: false,
			answer: null,
			after,
		};
		switch (request.method) {
			case "select":
				return { ...base, options: request.options ?? [], hunks: request.hunks };
			case "confirm":
				return { ...base, message: request.message ?? "" };
			case "input":
				return { ...base, placeholder: request.placeholder ?? "Enter value…" };
			case "editor":
				return { ...base, prefill: request.prefill ?? "" };
			case "ask": {
				const questions = window.OMP_ASK_DIALOG.parseQuestions(request.questions);
				return questions ? { ...base, questions, timeout: request.timeout ?? null, answers: null } : null;
			}
			default:
				return null;
		}
	}

	// ---------- socket ----------

	function useSession() {
		const [view, setView] = React.useState({
			cwd: "",
			state: { isStreaming: false, queuedMessages: { steering: [], followUp: [] } },
			raw: [],
			liveIndex: -1,
			asks: [],
			connected: false,
			stopped: false,
			version: 0,
		});
		const ref = React.useRef(null);
		if (!ref.current) {
			ref.current = {
				ws: null,
				retry: 0,
				seq: 0,
				pending: new Map(),
				tools: { partial: new Map(), ended: new Map(), cards: new Map(), timing: new Map() },
			};
		}
		const conn = ref.current;
		const [toasts, setToasts] = React.useState([]);

		const toast = React.useCallback((text, tone) => {
			const id = ++conn.seq;
			setToasts(list => [...list, { id, text, tone }]);
			setTimeout(() => setToasts(list => list.filter(t => t.id !== id)), 6000);
		}, []);

		const send = React.useCallback(payload => {
			const ws = conn.ws;
			if (!ws || ws.readyState !== WebSocket.OPEN) return Promise.reject(new Error("Not connected"));
			const reqId = `r${++conn.seq}`;
			const { promise, resolve, reject } = Promise.withResolvers();
			conn.pending.set(reqId, { resolve, reject });
			ws.send(JSON.stringify({ reqId, ...payload }));
			return promise;
		}, []);

		const rpc = React.useCallback(command => send({ kind: "rpc", command }), [send]);

		const refreshState = React.useCallback(() => {
			clearTimeout(conn.stateTimer);
			conn.stateTimer = setTimeout(() => {
				rpc({ type: "get_state" }).then(state => setView(v => ({ ...v, state: { ...v.state, ...state } })), () => {});
			}, 150);
		}, [rpc]);

		const onEvent = React.useCallback(frame => {
			if (!frame || typeof frame.type !== "string") return;
			const tools = conn.tools;
			setView(v => {
				switch (frame.type) {
					case "agent_start":
						return { ...v, state: { ...v.state, isStreaming: true } };
					case "agent_end":
					case "session_settled":
						refreshState();
						return { ...v, liveIndex: -1, state: { ...v.state, isStreaming: false } };
					case "message_start": {
						if (!frame.message) return v;
						const raw = [...v.raw, frame.message];
						return { ...v, raw, liveIndex: frame.message.role === "assistant" ? raw.length - 1 : v.liveIndex };
					}
					case "message_update": {
						if (!frame.message || frame.message.role !== "assistant") return v;
						if (v.liveIndex < 0) {
							const raw = [...v.raw, frame.message];
							return { ...v, raw, liveIndex: raw.length - 1 };
						}
						const raw = v.raw.slice();
						raw[v.liveIndex] = frame.message;
						return { ...v, raw };
					}
					case "message_end": {
						if (!frame.message) return v;
						const raw = v.raw.slice();
						const at = frame.message.role === "assistant" && v.liveIndex >= 0 ? v.liveIndex : raw.length - 1;
						if (at >= 0 && raw[at]?.role === frame.message.role && raw[at]?.timestamp === frame.message.timestamp) {
							raw[at] = frame.message;
						} else if (frame.message.role === "assistant" || frame.message.role === "toolResult") {
							if (at >= 0 && frame.message.role === "assistant" && v.liveIndex >= 0) raw[at] = frame.message;
							else raw.push(frame.message);
						}
						return { ...v, raw, liveIndex: frame.message.role === "assistant" ? -1 : v.liveIndex };
					}
					case "tool_execution_start":
						tools.timing.set(frame.toolCallId, { start: Date.now() });
						return { ...v, version: v.version + 1 };
					case "tool_execution_update":
						if (frame.partialResult) tools.partial.set(frame.toolCallId, frame.partialResult);
						return { ...v, version: v.version + 1 };
					case "tool_execution_end":
						if (frame.result) tools.ended.set(frame.toolCallId, { ...frame.result, isError: !!frame.isError });
						if (tools.timing.has(frame.toolCallId)) tools.timing.get(frame.toolCallId).end = Date.now();
						return { ...v, version: v.version + 1 };
					case "queue_update":
						refreshState();
						return v;
					case "prompt_result":
						if (frame.status === "error" && frame.error) toast(frame.error.message || "Prompt failed", "error");
						return v;
					default:
						return v;
				}
			});
		}, [refreshState, toast]);

		const onUi = React.useCallback(request => {
			if (!request) return;
			if (request.method === "notify") {
				toast(request.message, request.notifyType);
				return;
			}
			setView(v => {
				if (request.method === "cancel") {
					return { ...v, asks: v.asks.map(a => (a.id === request.targetId && !a.answered && !a.cancelled ? { ...a, cancelled: true, closedByOmp: true } : a)) };
				}
				if (v.asks.some(a => a.id === request.id)) return v;
				const ask = askFromRequest(request, v.raw.length - 1);
				return ask ? { ...v, asks: [...v.asks, ask] } : v;
			});
		}, [toast]);

		React.useEffect(() => {
			let closed = false;
			function connect() {
				const scheme = location.protocol === "https:" ? "wss" : "ws";
				const ws = new WebSocket(`${scheme}://${location.host}/ws`);
				conn.ws = ws;
				ws.addEventListener("open", () => {
					conn.retry = 0;
					setView(v => ({ ...v, connected: true }));
				});
				ws.addEventListener("message", event => {
					let msg;
					try {
						msg = JSON.parse(event.data);
					} catch {
						return;
					}
					switch (msg.kind) {
						case "hello": {
							conn.tools = { partial: new Map(), ended: new Map(), cards: new Map(), timing: new Map() };
							const raw = Array.isArray(msg.messages) ? msg.messages : [];
							const asks = [];
							for (const request of msg.pendingDialogs || []) {
								const ask = askFromRequest(request, raw.length - 1);
								if (ask) asks.push(ask);
							}
							document.title = `NPi · ${(msg.cwd || "").split("/").filter(Boolean).pop() || "Web"}`;
							setView(v => ({
								...v,
								cwd: msg.cwd || "",
								state: { ...v.state, ...msg.state },
								raw,
								liveIndex: msg.state?.isStreaming && raw.at(-1)?.role === "assistant" ? raw.length - 1 : -1,
								asks,
								connected: true,
							}));
							break;
						}
						case "event":
							onEvent(msg.frame);
							break;
						case "ui":
							onUi(msg.request);
							break;
						case "ui_resolved":
							setView(v => ({
								...v,
								asks: v.asks.map(a => (a.id === msg.id && !a.answered && !a.cancelled ? { ...a, answered: true } : a)),
							}));
							break;
						case "result": {
							const waiter = conn.pending.get(msg.reqId);
							if (!waiter) break;
							conn.pending.delete(msg.reqId);
							if (msg.ok) waiter.resolve(msg.data);
							else waiter.reject(new Error(msg.error || "Failed"));
							break;
						}
						case "error":
							toast(msg.message, "error");
							break;
						default:
							break;
					}
				});
				ws.addEventListener("close", event => {
					for (const waiter of conn.pending.values()) waiter.reject(new Error("Disconnected"));
					conn.pending.clear();
					const stopped = event.code === 1001 && event.reason === "Server stopped";
					setView(v => ({ ...v, connected: false, stopped }));
					if (closed || stopped) return;
					setTimeout(connect, Math.min(15000, 500 * 2 ** conn.retry++));
				});
			}
			connect();
			return () => {
				closed = true;
				conn.ws?.close();
			};
		}, [onEvent, onUi, toast]);

		/** Answer a dialog: the bubble settles at once, the server's verdict can undo it. */
		const answer = React.useCallback((id, patch, response) => {
			setView(v => ({ ...v, asks: v.asks.map(a => (a.id === id ? { ...a, ...patch } : a)) }));
			return send({ kind: "ui_response", response: { id, ...response } }).then(
				() => true,
				error => {
					toast(String(error.message || error), "error");
					return false;
				},
			);
		}, [send, toast]);

		const tools = React.useCallback(() => conn.tools, []);
		return { view, toasts, rpc, answer, toast, refreshState, tools };
	}

	// ---------- page ----------

	function Header({ cwd, state, connected, stopped }) {
		const model = state.model ? state.model.name || state.model.id : "no model";
		const status = stopped ? "stopped" : !connected ? "offline" : state.isStreaming ? "working" : "connected";
		return h(
			"header",
			{ className: "web-head" },
			h("span", { className: "web-brand" }, "NPi"),
			h(
				"div",
				{ className: "web-where" },
				h("div", { className: "web-cwd mono", title: cwd }, cwd),
				h(
					"div",
					{ className: "web-meta" },
					[state.sessionName, model, state.thinkingLevel ? `thinking ${state.thinkingLevel}` : null].filter(Boolean).join(" · "),
				),
			),
			h("span", { className: `web-conn ${status}` }, h("span", { className: "web-dot" }), status),
		);
	}

	function Composer({ streaming, connected, onSend, onAbort, queue, onRemoveQueued }) {
		const [text, setText] = React.useState("");
		const taRef = React.useRef(null);
		React.useLayoutEffect(() => {
			const ta = taRef.current;
			if (!ta) return;
			ta.style.height = "auto";
			ta.style.height = `${Math.min(ta.scrollHeight, 280)}px`;
		}, [text]);
		const sendable = connected && text.trim().length > 0;
		const submit = mode => {
			if (!sendable) return;
			const draft = text;
			setText("");
			onSend(draft, mode).catch(() => setText(prev => (prev ? prev : draft)));
		};
		const onKey = event => {
			if (event.key === "Enter" && !event.shiftKey && !event.isComposing) {
				event.preventDefault();
				submit(streaming ? "steer" : "send");
			} else if (event.key === "Escape" && streaming) {
				event.preventDefault();
				onAbort();
			}
		};
		const editQueued = row => {
			onRemoveQueued(row).then(ok => {
				if (ok) setText(prev => window.OMP_QUEUE.restoredDraft(row.text, prev));
			});
		};
		return h(
			"div",
			{ className: "composer" },
			h(QueueStrip, {
				queue,
				sending: [],
				canSendNow: false,
				canPromote: false,
				onSendNow: () => Promise.resolve(false),
				onPromote: () => Promise.resolve(false),
				onRemove: onRemoveQueued,
				onEdit: editQueued,
			}),
			h(
				"div",
				{ className: "composer-row" },
				h(
					"div",
					{ className: "composer-input" },
					h("textarea", {
						ref: taRef,
						rows: 1,
						value: text,
						className: "selectable",
						placeholder: streaming ? "steer the agent, or queue a follow-up…" : "what should we ship?",
						onChange: e => setText(e.target.value),
						onKeyDown: onKey,
					}),
				),
				streaming
					? h(
							React.Fragment,
							null,
							h(
								"button",
								{
									className: "btn outlined",
									onClick: () => submit("steer"),
									disabled: !sendable,
									style: { color: "var(--amber)", borderColor: "color-mix(in oklab, var(--amber) 40%, var(--line))" },
								},
								h(Icon, { name: "arrow", size: 10, color: "var(--amber)" }),
								" steer",
							),
							h("button", { className: "btn outlined", onClick: () => submit("queue"), disabled: !sendable }, "queue"),
							h(
								"button",
								{ className: "btn danger", onClick: onAbort },
								h(Icon, { name: "stop", size: 10 }),
								" abort ",
								h("span", { className: "kbd" }, "esc"),
							),
						)
					: h(
							"button",
							{ className: "btn primary", onClick: () => submit("send"), disabled: !sendable },
							"send ",
							h(Icon, { name: "arrow", size: 11 }),
						),
			),
		);
	}

	function App() {
		const { view, toasts, rpc, answer, toast, refreshState, tools } = useSession();
		const { state, connected } = view;
		const streaming = !!state.isStreaming;
		const [overrides, setOverrides] = React.useState(window.OMP_COLLAPSE.NO_OVERRIDES);
		const foldModes = React.useMemo(() => window.OMP_COLLAPSE.foldModes({}), []);

		const messages = React.useMemo(
			// `version` moves when streamed tool output lands in the connection's tool maps.
			() => buildEntries(view.raw, view.liveIndex, tools(), view.asks),
			[view.raw, view.liveIndex, view.asks, view.version, tools],
		);

		const onSend = React.useCallback(
			(message, mode) => {
				const command =
					!streaming ? { type: "prompt", message } : mode === "queue" ? { type: "follow_up", message } : { type: "steer", message };
				return rpc(command).then(refreshState, error => {
					toast(String(error.message || error), "error");
					throw error;
				});
			},
			[streaming, rpc, refreshState, toast],
		);
		const onAbort = React.useCallback(() => {
			rpc({ type: "abort" }).catch(error => toast(String(error.message || error), "error"));
		}, [rpc, toast]);
		const onRemoveQueued = React.useCallback(
			row =>
				rpc({ type: "remove_queued_message", message: row.text, queue: row.kind }).then(
					data => {
						refreshState();
						return data?.removed !== false;
					},
					() => false,
				),
			[rpc, refreshState],
		);

		const onAskAnswer = React.useCallback(
			(id, value) => {
				const payload = typeof value === "string" ? { value } : value;
				return answer(id, { answered: true, answer: payload.value }, payload);
			},
			[answer],
		);
		const onAskDialogAnswer = React.useCallback((id, answers) => answer(id, { answered: true, answers }, { answers }), [answer]);
		const onConfirmAsk = React.useCallback(
			(id, confirmed) => answer(id, { answered: true, answer: confirmed ? "Confirm" : "Deny" }, { confirmed }),
			[answer],
		);
		const onCancelAsk = React.useCallback(id => answer(id, { cancelled: true }, { cancelled: true }), [answer]);
		const onToggleCollapse = React.useCallback((id, collapsed) => setOverrides(o => ({ ...o, [id]: !collapsed })), []);

		const queue = state.queuedMessages || { steering: [], followUp: [] };
		return h(
			"div",
			{ className: "web-app" },
			h(Header, { cwd: view.cwd, state, connected, stopped: view.stopped }),
			h(
				"main",
				{ className: "session web-session" },
				h(ChatView, {
					messages,
					streaming,
					onAskAnswer,
					onAskDialogAnswer,
					onConfirmAsk,
					onCancelAsk,
					onGrantApproval: null,
					hasProjectPath: false,
					foldModes,
					collapseAfter: undefined,
					collapseOverrides: overrides,
					onToggleCollapse,
					followOutput: true,
					submitKey: "enter",
				}),
				view.stopped
					? h("div", { className: "web-banner" }, "The web UI was stopped in the terminal. Run /web there to start it again.")
					: h(Composer, { streaming, connected, onSend, onAbort, queue: { steering: queue.steering || [], followUp: queue.followUp || [] }, onRemoveQueued }),
			),
			h(
				"div",
				{ className: "web-toasts" },
				toasts.map(t => h("div", { key: t.id, className: `web-toast ${t.tone || ""}` }, t.text)),
			),
		);
	}

	// Light or dark like the system, with Desktop's Ivory / Graphite themes.
	const media = window.matchMedia("(prefers-color-scheme: light)");
	const applyTheme = () => document.documentElement.classList.toggle("theme-ivory", media.matches);
	applyTheme();
	media.addEventListener("change", applyTheme);

	const rootEl = document.getElementById("root");
	ReactDOM.createRoot(rootEl).render(h(App));
})();
